/** names Typst still reads but warns about (whole symbols, modules and single variants) */
export const TYPST_DEPRECATED: ReadonlySet<string> = new Set([
  'gt.tri',
  'gt.tri.eq',
  'gt.tri.eq.not',
  'gt.tri.not',
  'lt.tri',
  'lt.tri.eq',
  'lt.tri.eq.not',
  'lt.tri.not',
  'join',
  'tack.r.double',
  'tack.r.double.not',
  'tack.l.double',
  'tack.t.double',
  'tack.b.double',
]);
